        #region Equals and Hash
        public override bool Equals(object? obj)
        {
            if (obj is not IFalloutNVModGetter rhs) return false;
            return ((FalloutNVModCommon)((IFalloutNVModGetter)this).CommonInstance()!).Equals(this, rhs, equalsMask: null);
        }

