                    if (printMask?.SleepDeprivationStages?.Overall ?? true)
                    {
                        SleepDeprivationStages?.Print(sb);
                    }
                    if (printMask?.FormLists?.Overall ?? true)
                    {
                        FormLists?.Print(sb);
                    }
                }
            }
            #endregion

        }

