        public static IFalloutNVModDisposableGetter CreateFromBinaryOverlay(
            ModPath path,
            FalloutNVRelease release,
            BinaryReadParameters? param = null)
        {
            return FalloutNVModBinaryOverlay.FalloutNVModFactory(
                path: path,
                release: release,
                param: param);
        }

        public static IFalloutNVModDisposableGetter CreateFromBinaryOverlay(
            Stream stream,
            FalloutNVRelease release,
            ModKey modKey,
            BinaryReadParameters? param = null)
        {
            param ??= BinaryReadParameters.Default;
            var meta = ParsingMeta.Factory(param, release.ToGameRelease(), modKey, stream);
            return FalloutNVModBinaryOverlay.FalloutNVModFactory(
                stream: new MutagenBinaryReadStream(stream, meta),
                modKey: modKey,
                release: release,
                shouldDispose: false);
        }

        public static FalloutNVMod CreateFromBinary(
            MutagenFrame frame,
            FalloutNVRelease release,
            GroupMask? importMask = null)
        {
            try
            {
                var ret = new FalloutNVMod(
                    modKey: frame.MetaData.ModKey,
                    release: release);
                ((FalloutNVModSetterCommon)((IFalloutNVModGetter)ret).CommonSetterInstance()!).CopyInFromBinary(
                    item: ret,
                    frame: frame,
                    release: release,
                    importMask: importMask);
                return ret;
            }
            catch (Exception ex)
            {
                RecordException.EnrichAndThrow(ex, frame.MetaData.ModKey);
                throw;
            }
        }

