        public IEnumerable<IMajorRecord> EnumerateMajorRecords(IFalloutNVMod obj)
        {
            var ret = EnumerateMajorRecordsLoopLogic(obj: obj);
            if (obj is IMod)
            {
                ret = ret.ToList();
            }
            return ret;
        }
        
        public IEnumerable<IMajorRecord> EnumerateMajorRecordsLoopLogic(IFalloutNVMod obj)
        {
            foreach (var item in FalloutNVModCommon.Instance.EnumerateMajorRecords(obj))
            {
                yield return (item as IMajorRecord)!;
            }
        }
        
