        public void Print(
            IFalloutNVModGetter item,
            StructuredStringBuilder sb,
            string? name = null,
            FalloutNVMod.Mask<bool>? printMask = null)
        {
            if (name == null)
            {
                sb.AppendLine($"FalloutNVMod =>");
            }
            else
            {
                sb.AppendLine($"{name} (FalloutNVMod) =>");
            }
            using (sb.Brace())
            {
                ToStringFields(
                    item: item,
                    sb: sb,
                    printMask: printMask);
            }
        }
        
