        public IEnumerable<IModContext<IFalloutNVMod, IFalloutNVModGetter, IMajorRecord, IMajorRecordGetter>> EnumerateMajorRecordContexts(
            IFalloutNVModGetter obj,
            ILinkCache linkCache,
            Type type,
            bool throwIfUnknown)
        {
            switch (type.Name)
            {
                case "IMajorRecord":
                case "MajorRecord":
                case "IFalloutNVMajorRecord":
                case "FalloutNVMajorRecord":
                    if (!FalloutNVMod_Registration.SetterType.IsAssignableFrom(obj.GetType())) yield break;
                    foreach (var item in this.EnumerateMajorRecordContexts(
                        obj,
                        linkCache: linkCache))
                    {
                        yield return item;
                    }
                    yield break;
                case "IMajorRecordGetter":
                case "IFalloutNVMajorRecordGetter":
                    foreach (var item in this.EnumerateMajorRecordContexts(
                        obj,
