    /// <summary>
    /// Different game release versions a FalloutNV mod can have
    /// </summary>
    public enum FalloutNVRelease
    {
        FalloutNV = 13
    }

    public static class FalloutNVReleaseExt
    {
        public static GameRelease ToGameRelease(this FalloutNVRelease release)
        {
            return release switch
            {
                FalloutNVRelease.FalloutNV => GameRelease.FalloutNV,
                _ => throw new ArgumentException()
            };
        }

        public static FalloutNVRelease ToFalloutNVRelease(this GameRelease release)
        {
            return release switch
            {
                GameRelease.FalloutNV => FalloutNVRelease.FalloutNV,
                _ => throw new ArgumentException()
            };
        }
    }
