        protected FalloutNVModBinaryOverlay(
            IMutagenReadStream stream,
            ModKey modKey,
            bool shouldDispose,
            FalloutNVRelease release)
        {
            this.ModKey = modKey;
            this.FalloutNVRelease = release;
            this._stream = stream;
            this._package = new BinaryOverlayFactoryPackage(stream.MetaData);
            this._shouldDispose = shouldDispose;
        }

        public static FalloutNVModBinaryOverlay FalloutNVModFactory(
            ModPath path,
            FalloutNVRelease release,
            BinaryReadParameters? param)
        {
            param ??= BinaryReadParameters.Default;
            var meta = ParsingMeta.Factory(param, release.ToGameRelease(), path);
            meta.RecordInfoCache = new RecordTypeInfoCacheReader(() => new MutagenBinaryReadStream(path, meta), path.ModKey, meta.LinkCache);
            var stream = new MutagenBinaryReadStream(
                path: path.Path,
                metaData: meta);
            try
            {
                return FalloutNVModFactory(
                    stream: stream,
                    path.ModKey,
                    release: release,
                    shouldDispose: true);
            }
            catch (Exception ex)
            {
                stream.Dispose();
                throw ModGroupsMalformedException.Enrich(ex, path.ModKey);
            }
        }

        public static FalloutNVModBinaryOverlay FalloutNVModFactory(
            IMutagenReadStream stream,
            ModKey modKey,
            FalloutNVRelease release,
            bool shouldDispose)
        {
            var ret = new FalloutNVModBinaryOverlay(
                stream: stream,
                release: release,
                modKey: modKey,
                shouldDispose: shouldDispose);
            PluginBinaryOverlay.FillModTypes(
                stream: stream,
                package: ret._package,
                fill: ret.FillRecordType);
            return ret;
        }


